{"command":"python3 - <<'PY'
import json
from collections import Counter
from pathlib import Path

findings = json.loads(Path('data/findings.json').read_text())
report = json.loads(Path('reports/summary.json').read_text())

errors = []

# Exactly the three required keys
if set(report.keys()) != {'total_findings', 'severity_counts', 'open_finding_ids'}:
    errors.append(f"top-level keys wrong: {sorted(report.keys())}")

# total_findings: integer equal to record count
if not isinstance(report['total_findings'], int) or isinstance(report['total_findings'], bool):
    errors.append("total_findings is not an integer")
elif report['total_findings'] != len(findings):
    errors.append(f"total_findings {report['total_findings']} != {len(findings)}")

# severity_counts: exactly critical/high/medium/low with correct integer counts
expected_counts = Counter(f['severity'] for f in findings)
sc = report['severity_counts']
if set(sc.keys()) != {'critical', 'high', 'medium', 'low'}:
    errors.append(f"severity_counts keys wrong: {sorted(sc.keys())}")
for s in ('critical', 'high', 'medium', 'low'):
    if not isinstance(sc.get(s), int) or isinstance(sc.get(s), bool):
        errors.append(f"severity_counts[{s!r}] is not an integer")
    elif sc[s] != expected_counts.get(s, 0):
        errors.append(f"severity_counts[{s!r}] {sc[s]} != {expected_counts.get(s, 0)}")

# open_finding_ids: IDs with status 'open' in input order
expected_open = [f['id'] for f in findings if f['status'] == 'open']
if report['open_finding_ids'] != expected_open:
    errors.append(f"open_finding_ids {report['open_finding_ids']} != {expected_open}")

if errors:
    print("VALIDATION FAILED:")
    for e in errors: print(" -", e)
    raise SystemExit(1)
print("VALIDATION PASSED")
print(json.dumps(report, indent=2))
